/* Analytics, one pipeline: every page of the creator page, the OnePage and each website is one event with the property it happened on. analytics_events gets the property (property_type creator_page, onepage or website, and property_id: the website's store_theme_installs id or the OnePage's id), the page's path, and a link's id and destination for the new link_click event, which the event type check now allows (NOT VALID: old rows are not rechecked). Four indexes for the reads the reports and the tracker make. Old page views get their property from the address they were recorded on (the path is left empty: for a visitor who accepted analytics the stored address is the visit's first page, not the page itself); a second run changes nothing. A daily rollup per creator, property and UTC day (analytics_property_daily), the days it holds (analytics_rollup_days) and the function that refreshes a day (analytics_refresh_property_day), which the daily cron calls; server only, creators may read their own rows. analytics_visit_tally and analytics_all_time leave OnePage page views out, so the Storelib view counts them once, as before, in the OnePage view. docs/analytics/events.md is the contract. Run after 25 and 32. Can take a minute on a large events table. */
ALTER TABLE public.analytics_events ADD COLUMN IF NOT EXISTS visitor_id text, ADD COLUMN IF NOT EXISTS session_id text, ADD COLUMN IF NOT EXISTS referrer text, ADD COLUMN IF NOT EXISTS referrer_domain text, ADD COLUMN IF NOT EXISTS utm_source text, ADD COLUMN IF NOT EXISTS utm_medium text, ADD COLUMN IF NOT EXISTS utm_campaign text, ADD COLUMN IF NOT EXISTS utm_term text, ADD COLUMN IF NOT EXISTS utm_content text, ADD COLUMN IF NOT EXISTS country_code text, ADD COLUMN IF NOT EXISTS country_name text, ADD COLUMN IF NOT EXISTS region text, ADD COLUMN IF NOT EXISTS city text, ADD COLUMN IF NOT EXISTS device_type text, ADD COLUMN IF NOT EXISTS browser text, ADD COLUMN IF NOT EXISTS os text, ADD COLUMN IF NOT EXISTS page_url text, ADD COLUMN IF NOT EXISTS screen_width integer, ADD COLUMN IF NOT EXISTS screen_height integer, ADD COLUMN IF NOT EXISTS language text, ADD COLUMN IF NOT EXISTS source_category text, ADD COLUMN IF NOT EXISTS property_type text, ADD COLUMN IF NOT EXISTS property_id uuid, ADD COLUMN IF NOT EXISTS path text, ADD COLUMN IF NOT EXISTS link_id text, ADD COLUMN IF NOT EXISTS link_url text;
ALTER TABLE public.analytics_events DROP CONSTRAINT IF EXISTS analytics_events_event_type_check;
ALTER TABLE public.analytics_events ADD CONSTRAINT analytics_events_event_type_check CHECK (event_type IN ('view', 'purchase', 'session_start', 'store_view', 'product_view', 'add_to_cart', 'checkout_start', 'buy_click', 'checkout_complete', 'download', 'link_click')) NOT VALID;
ALTER TABLE public.analytics_events DROP CONSTRAINT IF EXISTS analytics_events_property_type_check;
ALTER TABLE public.analytics_events ADD CONSTRAINT analytics_events_property_type_check CHECK (property_type IS NULL OR property_type IN ('creator_page', 'onepage', 'website')) NOT VALID;
ALTER TABLE public.analytics_events DROP CONSTRAINT IF EXISTS analytics_events_path_check;
ALTER TABLE public.analytics_events ADD CONSTRAINT analytics_events_path_check CHECK (path IS NULL OR (char_length(path) <= 300 AND left(path, 1) = '/')) NOT VALID;
CREATE INDEX IF NOT EXISTS idx_analytics_events_property_type_time ON public.analytics_events (creator_id, property_type, property_id, event_type, created_at);
CREATE INDEX IF NOT EXISTS idx_analytics_events_property_path_time ON public.analytics_events (creator_id, property_type, property_id, path, created_at) WHERE event_type = 'view' AND path IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_analytics_events_visitor_time ON public.analytics_events (visitor_id, created_at) WHERE visitor_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_analytics_events_time_brin ON public.analytics_events USING brin (created_at);
DO $$ DECLARE has_purpose boolean; creator_hosts text := $h$ ('storelib.com', 'www.storelib.com', 'localhost', '127.0.0.1') $h$; v_rows bigint; BEGIN has_purpose := EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'custom_domains' AND column_name = 'purpose'); EXECUTE format($q$ WITH sole AS (SELECT creator_id, (array_agg(id))[1] AS install_id FROM public.store_theme_installs GROUP BY creator_id HAVING count(*) = 1), placed AS ( SELECT e.id, e.creator_id, %1$s AS host FROM public.analytics_events e WHERE e.property_type IS NULL AND e.event_type = 'view' AND e.page_url ~* '^https?://[^/?#]+' ), typed AS ( SELECT p.id, p.creator_id, CASE WHEN p.host IN %2$s OR p.host LIKE '%%.vercel.app' THEN 'creator_page' WHEN %3$s THEN 'creator_page' ELSE 'website' END AS property_type FROM placed p WHERE p.host IS NOT NULL ) UPDATE public.analytics_events e SET property_type = t.property_type, property_id = CASE WHEN t.property_type = 'website' THEN (SELECT s.install_id FROM sole s WHERE s.creator_id = t.creator_id) END FROM typed t WHERE e.id = t.id AND e.property_type IS NULL $q$, 'lower(substring(e.page_url from ''^[a-zA-Z][a-zA-Z0-9+.-]*://([^/?#:]+)''))', creator_hosts, CASE WHEN has_purpose THEN $c$EXISTS (SELECT 1 FROM public.custom_domains d WHERE d.creator_id = p.creator_id AND d.domain = regexp_replace(p.host, '^www\.', '') AND d.purpose = 'creator_page')$c$ ELSE 'false' END); GET DIAGNOSTICS v_rows = ROW_COUNT; RAISE NOTICE 'analytics_events: % old page views placed on a property', v_rows; END $$;
CREATE TABLE IF NOT EXISTS public.analytics_property_daily ( creator_id uuid NOT NULL, property_type text NOT NULL, property_id uuid, day date NOT NULL, visitors integer NOT NULL DEFAULT 0, sessions integer NOT NULL DEFAULT 0, bounces integer NOT NULL DEFAULT 0, page_views integer NOT NULL DEFAULT 0, product_views integer NOT NULL DEFAULT 0, link_clicks integer NOT NULL DEFAULT 0, buy_clicks integer NOT NULL DEFAULT 0, checkout_starts integer NOT NULL DEFAULT 0, sources jsonb NOT NULL DEFAULT '{}'::jsonb, referrers jsonb NOT NULL DEFAULT '{}'::jsonb, campaigns jsonb NOT NULL DEFAULT '{}'::jsonb, devices jsonb NOT NULL DEFAULT '{}'::jsonb, countries jsonb NOT NULL DEFAULT '{}'::jsonb, paths jsonb NOT NULL DEFAULT '{}'::jsonb, landing_paths jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT analytics_property_daily_type_check CHECK (property_type IN ('creator_page', 'onepage', 'website')) );
CREATE UNIQUE INDEX IF NOT EXISTS analytics_property_daily_key ON public.analytics_property_daily (creator_id, property_type, (coalesce(property_id, '00000000-0000-0000-0000-000000000000'::uuid)), day);
CREATE INDEX IF NOT EXISTS analytics_property_daily_day ON public.analytics_property_daily (day);
ALTER TABLE public.analytics_property_daily ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "creators read own property days" ON public.analytics_property_daily;
CREATE POLICY "creators read own property days" ON public.analytics_property_daily FOR SELECT USING (creator_id IN (SELECT c.id FROM public.creators c WHERE c.user_id = (SELECT auth.uid())));
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.analytics_property_daily FROM anon, authenticated;
CREATE TABLE IF NOT EXISTS public.analytics_rollup_days (day date PRIMARY KEY, refreshed_at timestamptz NOT NULL DEFAULT now(), properties integer NOT NULL DEFAULT 0);
ALTER TABLE public.analytics_rollup_days ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.analytics_rollup_days FROM anon, authenticated;
CREATE OR REPLACE FUNCTION public.analytics_refresh_property_day(p_day date, p_creator_id uuid DEFAULT NULL) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ DECLARE v_d0 timestamptz; v_d1 timestamptz; v_rows integer; BEGIN IF p_day IS NULL THEN RAISE EXCEPTION 'analytics_refresh_property_day: a day is needed'; END IF; v_d0 := p_day::timestamp AT TIME ZONE 'UTC'; v_d1 := (p_day + 1)::timestamp AT TIME ZONE 'UTC'; PERFORM pg_advisory_xact_lock(hashtext('analytics_property_daily:' || p_day::text)); DELETE FROM public.analytics_property_daily WHERE day = p_day AND (p_creator_id IS NULL OR creator_id = p_creator_id); INSERT INTO public.analytics_property_daily (creator_id, property_type, property_id, day, visitors, sessions, bounces, page_views, product_views, link_clicks, buy_clicks, checkout_starts, sources, referrers, campaigns, devices, countries, paths, landing_paths, updated_at) WITH ev AS ( SELECT e.id, e.creator_id, e.property_type, e.property_id, e.event_type, e.product_id, e.created_at, coalesce(e.path, '(unknown)') AS path, coalesce(nullif(e.source_category, ''), 'direct') AS source, coalesce(nullif(lower(regexp_replace(coalesce(e.referrer_domain, ''), '^www\.', '')), ''), 'direct') AS referrer, nullif(e.utm_campaign, '') AS campaign, coalesce(nullif(lower(e.device_type), ''), 'unknown') AS device, coalesce(nullif(upper(e.country_code), ''), 'unknown') AS country, e.property_type || ':' || coalesce(e.property_id::text, '') AS pk, coalesce(nullif(e.visitor_id::text, ''), nullif(e.session_id::text, ''), 'e:' || e.id::text) AS vkey, CASE WHEN coalesce(e.session_id::text, '') <> '' THEN 's:' || e.session_id::text WHEN coalesce(e.visitor_id::text, '') <> '' THEN 'v:' || e.visitor_id::text || ':' || to_char(e.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD') ELSE 'e:' || e.id::text END AS skey FROM public.analytics_events e WHERE e.created_at >= v_d0 - interval '1 day' AND e.created_at < v_d1 AND e.property_type IS NOT NULL AND e.event_type IN ('view', 'link_click', 'buy_click', 'checkout_start') AND (p_creator_id IS NULL OR e.creator_id = p_creator_id) ), today AS (SELECT * FROM ev WHERE created_at >= v_d0), views AS (SELECT * FROM ev WHERE event_type = 'view'), firsts AS (SELECT DISTINCT ON (creator_id, pk, skey) creator_id, pk, skey, created_at, path, source, referrer, campaign, device, country FROM views ORDER BY creator_id, pk, skey, created_at, id), pages AS (SELECT creator_id, pk, skey, count(*) AS n FROM views GROUP BY 1, 2, 3), starts AS (SELECT f.*, p.n AS pages FROM firsts f JOIN pages p USING (creator_id, pk, skey) WHERE f.created_at >= v_d0), keys AS (SELECT DISTINCT creator_id, pk, property_type, property_id FROM today), counts AS ( SELECT creator_id, pk, count(*) FILTER (WHERE event_type = 'view') AS page_views, count(*) FILTER (WHERE event_type = 'view' AND product_id IS NOT NULL) AS product_views, count(DISTINCT vkey) FILTER (WHERE event_type = 'view') AS visitors, count(*) FILTER (WHERE event_type = 'link_click') AS link_clicks, count(DISTINCT skey) FILTER (WHERE event_type = 'buy_click') AS buy_clicks, count(DISTINCT skey) FILTER (WHERE event_type = 'checkout_start') AS checkout_starts FROM today GROUP BY 1, 2 ), sessions AS (SELECT creator_id, pk, count(*) AS sessions, count(*) FILTER (WHERE pages = 1) AS bounces FROM starts GROUP BY 1, 2), by_source AS (SELECT creator_id, pk, jsonb_object_agg(k, n) AS m FROM (SELECT creator_id, pk, CASE WHEN rn <= 100 THEN source ELSE '(other)' END AS k, sum(n) AS n FROM (SELECT creator_id, pk, source, count(*) AS n, row_number() OVER (PARTITION BY creator_id, pk ORDER BY count(*) DESC, source) AS rn FROM starts GROUP BY 1, 2, 3) a GROUP BY 1, 2, 3) b GROUP BY 1, 2), by_referrer AS (SELECT creator_id, pk, jsonb_object_agg(k, n) AS m FROM (SELECT creator_id, pk, CASE WHEN rn <= 100 THEN referrer ELSE '(other)' END AS k, sum(n) AS n FROM (SELECT creator_id, pk, referrer, count(*) AS n, row_number() OVER (PARTITION BY creator_id, pk ORDER BY count(*) DESC, referrer) AS rn FROM starts GROUP BY 1, 2, 3) a GROUP BY 1, 2, 3) b GROUP BY 1, 2), by_campaign AS (SELECT creator_id, pk, jsonb_object_agg(k, n) AS m FROM (SELECT creator_id, pk, CASE WHEN rn <= 100 THEN campaign ELSE '(other)' END AS k, sum(n) AS n FROM (SELECT creator_id, pk, campaign, count(*) AS n, row_number() OVER (PARTITION BY creator_id, pk ORDER BY count(*) DESC, campaign) AS rn FROM starts WHERE campaign IS NOT NULL GROUP BY 1, 2, 3) a GROUP BY 1, 2, 3) b GROUP BY 1, 2), by_device AS (SELECT creator_id, pk, jsonb_object_agg(k, n) AS m FROM (SELECT creator_id, pk, CASE WHEN rn <= 100 THEN device ELSE '(other)' END AS k, sum(n) AS n FROM (SELECT creator_id, pk, device, count(*) AS n, row_number() OVER (PARTITION BY creator_id, pk ORDER BY count(*) DESC, device) AS rn FROM starts GROUP BY 1, 2, 3) a GROUP BY 1, 2, 3) b GROUP BY 1, 2), by_country AS (SELECT creator_id, pk, jsonb_object_agg(k, n) AS m FROM (SELECT creator_id, pk, CASE WHEN rn <= 300 THEN country ELSE '(other)' END AS k, sum(n) AS n FROM (SELECT creator_id, pk, country, count(*) AS n, row_number() OVER (PARTITION BY creator_id, pk ORDER BY count(*) DESC, country) AS rn FROM starts GROUP BY 1, 2, 3) a GROUP BY 1, 2, 3) b GROUP BY 1, 2), by_path AS (SELECT creator_id, pk, jsonb_object_agg(k, n) AS m FROM (SELECT creator_id, pk, CASE WHEN rn <= 200 THEN path ELSE '(other)' END AS k, sum(n) AS n FROM (SELECT creator_id, pk, path, count(*) AS n, row_number() OVER (PARTITION BY creator_id, pk ORDER BY count(*) DESC, path) AS rn FROM today WHERE event_type = 'view' GROUP BY 1, 2, 3) a GROUP BY 1, 2, 3) b GROUP BY 1, 2), by_landing AS (SELECT creator_id, pk, jsonb_object_agg(k, n) AS m FROM (SELECT creator_id, pk, CASE WHEN rn <= 200 THEN path ELSE '(other)' END AS k, sum(n) AS n FROM (SELECT creator_id, pk, path, count(*) AS n, row_number() OVER (PARTITION BY creator_id, pk ORDER BY count(*) DESC, path) AS rn FROM starts GROUP BY 1, 2, 3) a GROUP BY 1, 2, 3) b GROUP BY 1, 2) SELECT k.creator_id, k.property_type, k.property_id, p_day, coalesce(c.visitors, 0), coalesce(s.sessions, 0), coalesce(s.bounces, 0), coalesce(c.page_views, 0), coalesce(c.product_views, 0), coalesce(c.link_clicks, 0), coalesce(c.buy_clicks, 0), coalesce(c.checkout_starts, 0), coalesce(src.m, '{}'::jsonb), coalesce(rf.m, '{}'::jsonb), coalesce(cp.m, '{}'::jsonb), coalesce(dv.m, '{}'::jsonb), coalesce(ct.m, '{}'::jsonb), coalesce(pt.m, '{}'::jsonb), coalesce(ld.m, '{}'::jsonb), now() FROM keys k LEFT JOIN counts c ON c.creator_id = k.creator_id AND c.pk = k.pk LEFT JOIN sessions s ON s.creator_id = k.creator_id AND s.pk = k.pk LEFT JOIN by_source src ON src.creator_id = k.creator_id AND src.pk = k.pk LEFT JOIN by_referrer rf ON rf.creator_id = k.creator_id AND rf.pk = k.pk LEFT JOIN by_campaign cp ON cp.creator_id = k.creator_id AND cp.pk = k.pk LEFT JOIN by_device dv ON dv.creator_id = k.creator_id AND dv.pk = k.pk LEFT JOIN by_country ct ON ct.creator_id = k.creator_id AND ct.pk = k.pk LEFT JOIN by_path pt ON pt.creator_id = k.creator_id AND pt.pk = k.pk LEFT JOIN by_landing ld ON ld.creator_id = k.creator_id AND ld.pk = k.pk; GET DIAGNOSTICS v_rows = ROW_COUNT; IF p_creator_id IS NULL THEN INSERT INTO public.analytics_rollup_days (day, refreshed_at, properties) VALUES (p_day, now(), v_rows) ON CONFLICT (day) DO UPDATE SET refreshed_at = excluded.refreshed_at, properties = excluded.properties; END IF; RETURN v_rows; END; $fn$;
REVOKE ALL ON FUNCTION public.analytics_refresh_property_day(date, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.analytics_refresh_property_day(date, uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.analytics_visit_tally( p_creator_id uuid, p_product_id uuid, p_time_zone text, p_cur_start bigint, p_cur_end bigint, p_prev_start bigint, p_prev_end bigint, p_cur_starts bigint[], p_prev_starts bigint[], p_detail boolean DEFAULT true ) RETURNS jsonb LANGUAGE sql STABLE SET search_path = public AS $fn$WITH bounds AS ( SELECT timestamptz 'epoch' + p_cur_start * interval '1 millisecond' AS cs, timestamptz 'epoch' + p_cur_end * interval '1 millisecond' AS ce, timestamptz 'epoch' + p_prev_start * interval '1 millisecond' AS ps, timestamptz 'epoch' + p_prev_end * interval '1 millisecond' AS pe, coalesce(cardinality(p_cur_starts), 0) AS n ), win AS ( SELECT 'cur'::text AS w, b.cs AS ws, b.ce AS we, ARRAY(SELECT timestamptz 'epoch' + x * interval '1 millisecond' FROM unnest(coalesce(p_cur_starts, '{}'::bigint[])) WITH ORDINALITY u(x, i) ORDER BY i) AS starts FROM bounds b UNION ALL SELECT 'prev'::text, b.ps, b.pe, ARRAY(SELECT timestamptz 'epoch' + x * interval '1 millisecond' FROM unnest(coalesce(p_prev_starts, '{}'::bigint[])) WITH ORDINALITY u(x, i) ORDER BY i) FROM bounds b ), raw AS ( SELECT e.id, e.created_at, e.session_id::text AS session_id, e.visitor_id::text AS visitor_id, e.source_category, e.referrer_domain, e.utm_campaign, e.country_code, e.country_name, e.city, e.device_type, e.browser, e.os, e.page_url FROM public.analytics_events e, bounds b WHERE e.creator_id = p_creator_id AND e.event_type = 'view' AND (p_product_id IS NULL OR e.product_id = p_product_id) AND e.property_type IS DISTINCT FROM 'onepage' AND e.created_at >= b.cs AND e.created_at < b.ce UNION ALL SELECT e.id, e.created_at, e.session_id::text, e.visitor_id::text, e.source_category, e.referrer_domain, e.utm_campaign, e.country_code, e.country_name, e.city, e.device_type, e.browser, e.os, e.page_url FROM public.analytics_events e, bounds b WHERE e.creator_id = p_creator_id AND e.event_type = 'view' AND (p_product_id IS NULL OR e.product_id = p_product_id) AND e.property_type IS DISTINCT FROM 'onepage' AND e.created_at >= b.ps AND e.created_at < b.pe AND NOT (e.created_at >= b.cs AND e.created_at < b.ce) ), wrows AS ( SELECT w.w, r.id, r.created_at, CASE WHEN cardinality(w.starts) > 0 THEN width_bucket(r.created_at, w.starts) - 1 END AS bucket, (CASE WHEN coalesce(r.session_id, '') <> '' THEN 's:' || r.session_id WHEN coalesce(r.visitor_id, '') <> '' THEN 'v:' || r.visitor_id || ':' || ( floor(extract(epoch FROM r.created_at))::bigint - floor(extract(epoch FROM (r.created_at AT TIME ZONE p_time_zone)::time))::bigint )::text ELSE 'e:' || r.id::text END) COLLATE "C" AS skey FROM raw r JOIN win w ON r.created_at >= w.ws AND r.created_at < w.we ), firsts AS ( SELECT DISTINCT ON (w, skey) w, skey, created_at, id, bucket FROM wrows ORDER BY w, skey, created_at, id ), ranked AS ( SELECT f.w, row_number() OVER (PARTITION BY f.w ORDER BY f.created_at, f.id) AS rank, r.source_category, r.referrer_domain, r.utm_campaign, r.country_code, r.country_name, r.city, r.device_type, r.browser, r.os, split_part(split_part(r.page_url, '#', 1), '?', 1) AS page_url FROM firsts f JOIN raw r ON r.id = f.id WHERE p_detail ), view_b AS (SELECT w, bucket, count(*) AS c FROM wrows GROUP BY w, bucket), session_b AS (SELECT w, bucket, count(*) AS c FROM firsts GROUP BY w, bucket), buckets AS ( SELECT w.w, coalesce((SELECT sum(v.c) FROM view_b v WHERE v.w = w.w), 0) AS views, coalesce((SELECT sum(s.c) FROM session_b s WHERE s.w = w.w), 0) AS sessions, coalesce((SELECT jsonb_agg(coalesce(v.c, 0) ORDER BY g.i) FROM bounds b, generate_series(0, b.n - 1) g(i) LEFT JOIN view_b v ON v.w = w.w AND v.bucket = g.i), '[]'::jsonb) AS view_buckets, coalesce((SELECT jsonb_agg(coalesce(s.c, 0) ORDER BY g.i) FROM bounds b, generate_series(0, b.n - 1) g(i) LEFT JOIN session_b s ON s.w = w.w AND s.bucket = g.i), '[]'::jsonb) AS session_buckets FROM win w ), steps AS ( SELECT w.w, s.event_type, count(DISTINCT s.skey) AS c FROM ( SELECT e.event_type, e.created_at, (CASE WHEN coalesce(e.session_id::text, '') <> '' THEN 's:' || e.session_id::text WHEN coalesce(e.visitor_id::text, '') <> '' THEN 'v:' || e.visitor_id::text || ':' || ( floor(extract(epoch FROM e.created_at))::bigint - floor(extract(epoch FROM (e.created_at AT TIME ZONE p_time_zone)::time))::bigint )::text ELSE 'e:' || e.created_at::text END) COLLATE "C" AS skey FROM public.analytics_events e, bounds b WHERE p_detail AND e.creator_id = p_creator_id AND e.event_type IN ('buy_click', 'checkout_start') AND (p_product_id IS NULL OR e.product_id = p_product_id) AND ((e.created_at >= b.cs AND e.created_at < b.ce) OR (e.created_at >= b.ps AND e.created_at < b.pe)) ) s JOIN win w ON s.created_at >= w.ws AND s.created_at < w.we GROUP BY w.w, s.event_type ), grouped AS ( SELECT w, CASE WHEN GROUPING(source_category) = 0 THEN 'source' WHEN GROUPING(referrer_domain) = 0 THEN 'referrer' WHEN GROUPING(utm_campaign) = 0 THEN 'campaign' WHEN GROUPING(city) = 0 THEN 'city' WHEN GROUPING(country_code) = 0 THEN 'country' WHEN GROUPING(device_type) = 0 THEN 'device' WHEN GROUPING(browser) = 0 THEN 'browser' WHEN GROUPING(os) = 0 THEN 'os' ELSE 'page' END AS kind, CASE WHEN GROUPING(source_category) = 0 THEN jsonb_build_array(source_category) WHEN GROUPING(referrer_domain) = 0 THEN jsonb_build_array(referrer_domain) WHEN GROUPING(utm_campaign) = 0 THEN jsonb_build_array(utm_campaign) WHEN GROUPING(city) = 0 THEN jsonb_build_array(city, country_code, country_name) WHEN GROUPING(country_code) = 0 THEN jsonb_build_array(country_code, country_name) WHEN GROUPING(device_type) = 0 THEN jsonb_build_array(device_type) WHEN GROUPING(browser) = 0 THEN jsonb_build_array(browser) WHEN GROUPING(os) = 0 THEN jsonb_build_array(os) ELSE jsonb_build_array(page_url) END AS cols, count(*) AS n, min(rank) AS r FROM ranked GROUP BY w, GROUPING SETS ((source_category), (referrer_domain), (utm_campaign), (country_code, country_name), (city, country_code, country_name), (device_type), (browser), (os), (page_url)) ), groups AS ( SELECT w, jsonb_object_agg(kind, rows) AS groups FROM (SELECT w, kind, jsonb_agg(cols || jsonb_build_array(n, r) ORDER BY r) AS rows FROM grouped GROUP BY w, kind) k GROUP BY w ), tallies AS ( SELECT w.w, jsonb_build_object( 'views', bk.views, 'view_buckets', bk.view_buckets, 'sessions', bk.sessions, 'session_buckets', bk.session_buckets, 'steps', CASE WHEN p_detail THEN jsonb_build_object( 'buy', coalesce((SELECT s.c FROM steps s WHERE s.w = w.w AND s.event_type = 'buy_click'), 0), 'checkout', coalesce((SELECT s.c FROM steps s WHERE s.w = w.w AND s.event_type = 'checkout_start'), 0) ) END, 'groups', CASE WHEN p_detail THEN coalesce((SELECT g.groups FROM groups g WHERE g.w = w.w), '{}'::jsonb) END ) AS t FROM win w JOIN buckets bk ON bk.w = w.w ) SELECT jsonb_object_agg(w, t) FROM tallies$fn$;
CREATE OR REPLACE FUNCTION public.analytics_all_time(p_creator_id uuid, p_product_id uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path = public AS $fn$WITH lines AS ( SELECT coalesce('s:' || nullif(o.stripe_session_id, ''), 'o:' || o.id::text) AS k, o.status, greatest(0, coalesce(o.amount_cents, 0))::bigint AS gross, CASE WHEN o.status = 'refunded' THEN CASE WHEN o.refund_amount_cents > 0 THEN least(o.refund_amount_cents, greatest(0, coalesce(o.amount_cents, 0))) ELSE greatest(0, coalesce(o.amount_cents, 0)) END ELSE 0 END::bigint AS refunded FROM public.orders o WHERE o.creator_id = p_creator_id AND (p_product_id IS NULL OR o.product_id = p_product_id) ), payments AS ( SELECT k, bool_and(coalesce(status = 'failed', false)) AS all_failed, bool_or(coalesce(status = 'pending', false)) AS any_pending, bool_or(coalesce(status = 'disputed', false)) AS any_disputed, greatest(0, sum(gross) - sum(refunded)) AS net FROM lines GROUP BY k ) SELECT jsonb_build_object( 'views', ( SELECT count(*) FROM public.analytics_events e WHERE e.creator_id = p_creator_id AND e.event_type = 'view' AND (p_product_id IS NULL OR e.product_id = p_product_id) AND e.property_type IS DISTINCT FROM 'onepage' ), 'orders', (SELECT count(*) FROM payments WHERE NOT all_failed AND NOT any_pending AND NOT any_disputed), 'sales_cents', (SELECT coalesce(sum(net), 0) FROM payments WHERE NOT all_failed AND NOT any_pending AND NOT any_disputed) )$fn$;
REVOKE ALL ON FUNCTION public.analytics_visit_tally(uuid, uuid, text, bigint, bigint, bigint, bigint, bigint[], bigint[], boolean) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.analytics_all_time(uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.analytics_visit_tally(uuid, uuid, text, bigint, bigint, bigint, bigint, bigint[], bigint[], boolean) TO service_role;
GRANT EXECUTE ON FUNCTION public.analytics_all_time(uuid, uuid) TO service_role;
notify pgrst, 'reload schema';
